# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/state — 调音台状态 + 唯一写入口 set_value + WriteSink + 电平/推送"""

import math
import struct
import threading
import time



# ---------------------------------------------------------------- 调音台状态

class MixerState:
    def __init__(self):
        self.lock = threading.Lock()
        self.ch = {i: {"fader": 0.75, "on": 1} for i in range(1, 33)}
        self.bus = {i: {"fader": 0.75, "on": 1} for i in range(1, 17)}   # 输出通道 Mix Bus 1-16
        self.dca = {i: {"fader": 0.75, "on": 1} for i in range(1, 9)}
        self.auxin = {i: {"fader": 0.75, "on": 1} for i in range(1, 7)}  # 辅助输入 Aux In 1-6
        self.usb = {i: {"fader": 0.75, "on": 1} for i in range(1, 3)}    # USB 播放返回 1-2
        self.fxret = {i: {"fader": 0.75, "on": 1} for i in range(1, 9)}  # 效果返回 FX Return 1-8
        self.mtx = {i: {"fader": 0.75, "on": 1} for i in range(1, 7)}    # 矩阵输出 Matrix 1-6
        self.main = {"fader": 0.75, "on": 1}
        self.scene = 1
        # FX 机架 1-8: 混响器. par 存**原生单位**参数值 (时间=秒 / 预延迟=毫秒 / 阻尼=0..1),
        # 参数索引随算法变化, 映射表见 X32_FX_ALGOS / M32_FX_ALGOS (默认值需真机标定)
        self.fx = {i: {"type": "", "name": "", "on": 1, "mix": 0.25, "par": {}}
                   for i in range(1, FX_COUNT + 1)}
        for i, algo in enumerate(("HALL", "PLATE", "ROOM", "CHAMBER")):
            if i + 1 <= FX_COUNT:
                self.fx[i + 1]["type"] = algo
                self.fx[i + 1]["par"] = dict(REVERB_DEFAULTS[algo])
        self.fx[1]["name"] = "主厅堂"
        self.fx[2]["name"] = "人声板"
        # DCA 成员表: {dca_idx: [ch_idx, ...]}; 手动推 DCA 时成员推子按 dB 差量级联
        # (与真台一致: /ch/XX/mix/dca 位掩码设置归属, 默认每 8 路一组)
        self.dca_members = {i: [] for i in range(1, 9)}
        for i in range(1, 33):
            self.dca_members[(i - 1) // 8 + 1].append(i)
        # 通道/输出名称: {(group, idx): str}, 卡片·推子行·控制键统一显示
        self.names = dict(DEFAULT_NAMES)

    def fader_to_db(self, f: float) -> float:
        if f <= 0.0:
            return -90.0
        if f >= 0.75:
            return (f - 0.75) / 0.25 * 10.0
        # 历史 bug：此处曾有 `if f <= 0.001: return -90.0`，把 -57.5dB 以下的整段
        # 塌陷成 -∞，导致 -60dB 无法往返（Android/Kotlin 端曾忠实照搬同一 bug）。
        # 改为对下限做 clamp，保住低段分辨率。
        return max(-90.0, 20.0 * math.log10(f / 0.75))


def db_to_fader(db: float) -> float:
    """fader_to_db 的逆运算:-90..+10 dB → 0..1 推子行程"""
    db = min(max(db, -90.0), 10.0)
    if db <= -89.5:
        return 0.0
    if db >= 10.0:
        return 1.0
    if db >= 0.0:
        return 0.75 + db / 10.0 * 0.25
    return 0.75 * (10.0 ** (db / 20.0))

STATE = MixerState()
METER_SUBSCRIBERS = {}      # {(ip, port): 最后活跃时间}; /meters /subscribe /xremote 续期, 30 秒超时清理
METER_LOCK = threading.Lock()
START_TIME = time.time()


def match_address(pattern: str):
    """按 X32 通配符匹配,返回 (group, index, kind) 列表。
    kind: 'ch_fader' | 'ch_on' | 'dca_fader' | 'dca_on' | 'main_fader' | 'main_on'
    """
    segs = pattern.strip("/").split("/")
    results = []

    def seg_match(pat, val):
        return pat == "*" or pat == val

    with STATE.lock:
        if len(segs) == 4 and segs[0] == "ch" and segs[2] == "mix":
            kind = {"fader": "ch_fader", "on": "ch_on", "dca": "ch_dca"}.get(segs[3])
            if kind:
                for i in sorted(STATE.ch):
                    if seg_match(segs[1], "%02d" % i):
                        results.append((kind, i))
        elif len(segs) == 4 and segs[0] == "bus" and segs[2] == "mix":
            kind = {"fader": "bus_fader", "on": "bus_on"}.get(segs[3])
            if kind:
                for i in sorted(STATE.bus):
                    if seg_match(segs[1], "%02d" % i):
                        results.append((kind, i))
        elif len(segs) == 3 and segs[0] == "dca":
            kind = {"fader": "dca_fader", "on": "dca_on"}.get(segs[2])
            if kind:
                for i in sorted(STATE.dca):
                    if seg_match(segs[1], "%02d" % i):
                        results.append((kind, i))
        elif len(segs) == 4 and segs[2] == "mix" and segs[0] in ("auxin", "usb", "fxret", "mtx"):
            kind = {"fader": segs[0] + "_fader", "on": segs[0] + "_on"}.get(segs[3])
            if kind:
                group = {"auxin": STATE.auxin, "usb": STATE.usb,
                         "fxret": STATE.fxret, "mtx": STATE.mtx}[segs[0]]
                val = segs[1].rstrip("LR")            # 真台 FX 返回常用 01L/01R 写法
                for i in sorted(group):
                    if seg_match(val, "%02d" % i):
                        results.append((kind, i))
        elif len(segs) == 4 and segs[0] == "main" and segs[1] == "st" and segs[2] == "mix":
            kind = {"fader": "main_fader", "on": "main_on"}.get(segs[3])
            if kind:
                results.append((kind, 0))
        elif len(segs) >= 3 and segs[0] == "fx" and segs[1].isdigit():
            # FX 机架: /fx/<槽>/type | on | mix | par/<参数号> | config/name
            # ⚠️ 槽号不补零 (/fx/1/...), 参数号补零 (/fx/1/par/01)
            slot = int(segs[1])
            if 1 <= slot <= FX_COUNT:
                if len(segs) == 3:
                    kind = {"type": "fx_type", "on": "fx_on", "mix": "fx_mix"}.get(segs[2])
                    if kind:
                        results.append((kind, slot))
                elif len(segs) == 4 and segs[2] == "par" and segs[3].isdigit():
                    p = int(segs[3])
                    if 1 <= p <= 64:
                        results.append((fx_par_kind(p), slot))
                elif len(segs) == 4 and segs[2] == "config" and segs[3] == "name":
                    results.append(("fx_name", slot))
    return results


def get_value(kind, idx):
    with STATE.lock:
        if kind == "ch_fader":  return float(STATE.ch[idx]["fader"])
        if kind == "ch_on":     return int(STATE.ch[idx]["on"])
        if kind == "ch_dca":    # 通道归属的 DCA 位掩码
            return sum(1 << (d - 1) for d in range(1, 9)
                       if idx in STATE.dca_members.get(d, []))
        if kind == "bus_fader": return float(STATE.bus[idx]["fader"])
        if kind == "bus_on":    return int(STATE.bus[idx]["on"])
        if kind == "dca_fader": return float(STATE.dca[idx]["fader"])
        if kind == "dca_on":    return int(STATE.dca[idx]["on"])
        if kind == "main_fader": return float(STATE.main["fader"])
        if kind == "main_on":   return int(STATE.main["on"])
        for g in ("auxin", "usb", "fxret", "mtx"):
            if kind == g + "_fader": return float(STATE.__dict__[g][idx]["fader"])
            if kind == g + "_on":    return int(STATE.__dict__[g][idx]["on"])
        if 1 <= idx <= FX_COUNT:
            fx = STATE.fx[idx]
            if kind == "fx_type": return fx["type"]
            if kind == "fx_name": return fx["name"]
            if kind == "fx_on":   return int(fx["on"])
            if kind == "fx_mix":  return float(fx["mix"])
            p = fx_par_num(kind)
            if p is not None:     return float(fx["par"].get(p, 0.0))
    return None


def target_exists(kind, idx):
    """本地台面是否存在这个目标。

    换控台后规模可能大于本地（例如 Wing 48 路 vs 本地 32 路），
    目标超出范围时要**明确跳过并记日志**，不能让 KeyError 冒出去。
    """
    try:
        return get_value(kind, idx) is not None
    except (KeyError, IndexError, TypeError):
        return False


def set_value(kind, idx, value, source="manual"):
    # 延迟导入: fx→state 是顶层依赖, state→fx 只在本函数用 —— 放这里打破环
    # (合成单文件形态下该行被剥离, 同一命名空间直接解析)。
    # source="manual" (网页/控制键/外部 OSC 默认) 会触发冲突检测;
    # source="action"/"dca"/"fade" 是卡片/回归/DCA 级联/渐变插值自己的写入, 不检测
    if source == "manual":
        _check_manual_takeover(kind, idx)
    cascade_from = None
    if kind == "dca_fader" and source == "manual":
        cascade_from = get_value(kind, idx)   # DCA 手动移动 → 成员级联基准
    with STATE.lock:
        if kind == "ch_fader":   STATE.ch[idx]["fader"] = _clamp01(value)
        elif kind == "ch_on":    STATE.ch[idx]["on"] = _truthy(value)
        elif kind == "ch_dca":   # 位掩码: 通道归属哪些 DCA (bit0=DCA1 ...)
            mask = int(value) & 0xFF
            for d in range(1, 9):
                members = STATE.dca_members[d]
                has = idx in members
                want = bool(mask & (1 << (d - 1)))
                if want and not has:
                    members.append(idx)
                    members.sort()
                elif has and not want:
                    members.remove(idx)
        elif kind == "bus_fader": STATE.bus[idx]["fader"] = _clamp01(value)
        elif kind == "bus_on":   STATE.bus[idx]["on"] = _truthy(value)
        elif kind == "dca_fader": STATE.dca[idx]["fader"] = _clamp01(value)
        elif kind == "dca_on":   STATE.dca[idx]["on"] = _truthy(value)
        elif kind == "main_fader": STATE.main["fader"] = _clamp01(value)
        elif kind == "main_on":  STATE.main["on"] = _truthy(value)
        elif 1 <= idx <= FX_COUNT:
            fx = STATE.fx[idx]
            if kind == "fx_type":
                fx["type"] = str(value).upper()[:8]
                # 换算法要重新铺一套该算法的默认参数, 否则参数索引会串味
                if fx["type"] in fx_algos():
                    fx["par"] = dict(REVERB_DEFAULTS.get(fx["type"], {}))
                else:
                    fx["par"] = {}
            elif kind == "fx_name": fx["name"] = str(value)[:12]
            elif kind == "fx_on":   fx["on"] = _truthy(value)
            elif kind == "fx_mix":  fx["mix"] = _clamp01(value)
            else:
                p = fx_par_num(kind)
                if p is not None:
                    fx["par"][p] = fx_par_clamp(idx, p, value)
        else:
            hit = False
            for g in ("auxin", "usb", "fxret", "mtx"):
                if kind == g + "_fader":
                    STATE.__dict__[g][idx]["fader"] = _clamp01(value)
                    hit = True
                elif kind == g + "_on":
                    STATE.__dict__[g][idx]["on"] = _truthy(value)
                    hit = True
            if not hit:
                # 走到这里说明 kind 完全不认识 —— 必须留痕。
                # 曾经的写法是"什么都不做"，于是一个拼错的 kind 表现成
                # "接口返回 ok 但台子没反应"，最难查的那类。
                log("SET 未识别的写入: kind=%r idx=%r value=%r (已忽略)"
                    % (kind, idx, value))
    if source == "manual":
        _push_manual_now(kind, idx)
    # 写出口 (WriteSink): 落库后的值交给各 sink。sink 只能拿到 after 值,
    # 物理上不可能再转发原始入参 (B0-2 的根因); 桥接/推送/冲突检测互不干扰。
    for _sink in SINKS:
        _sink.on_write(kind, idx, get_value(kind, idx), source)
    if cascade_from is not None:
        _dca_cascade(idx, cascade_from, _finite(value, 0.0))
    # 混响时间改动 → 按同步模式广播到联动组。
    # 三个入口(软件改 / Tap 换算 / 真台回读)最终都汇聚到 set_value, 所以只在这里挂一次;
    # 广播出去的写入用 source="action", 不会再触发本分支 —— 天然断开回环。
    p = fx_par_num(kind)
    if p is not None and source in ("manual", "sync"):
        algo = fx_algo(idx)
        if algo and p == algo["time"]:
            _fx_time_fanout(idx, get_value(kind, idx), source)


def _push_manual_now(kind, idx):
    """手动写入立即广播给订阅者 (真台行为: 面板动推子马上推送, 让桥接端及时察觉干预)。"""
    sock = MAIN_SOCK[0]
    if sock is None:
        return
    key = (kind, idx)
    v = get_value(kind, idx)
    if v is None:
        return
    # 节流: 只有"值没变且来得太快"才合并; 值一变就必须推 —— 否则桥接场景下真台的
    # 面板干预会被渐变转发的时间戳挤掉 (见 NOTIFY_LAST 注释)。
    now = time.time()
    with NOTIFY_LOCK:
        last = NOTIFY_LAST.get(key)
        if last is not None and last[0] == v and now - last[1] < 0.08:
            return
        NOTIFY_LAST[key] = [v, now]
    PUSH_CACHE[key] = v           # 立即推送后, 周期推送不再重发
    with METER_LOCK:
        subs = list(METER_SUBSCRIBERS)
    if not subs:
        return
    try:
        reply = value_reply(kind, idx)
        if reply is None:      # 当前控台没有该目标的地址
            return
        pkt = encode_message(reply)
    except Exception:
        return
    for s in subs:
        try:
            sock.sendto(pkt, s)
        except OSError:
            pass


def _dca_cascade(dca_idx, old_fader, new_fader):
    """手动推 DCA: 成员通道推子按 dB 差量级联 (真台手感)。
    卡片/回归写 DCA 走 source="action", 不级联。"""
    try:
        delta = STATE.fader_to_db(min(max(new_fader, 0.0), 1.0)) - \
            STATE.fader_to_db(min(max(old_fader, 0.0), 1.0))
    except Exception:
        return
    if abs(delta) < 0.01:
        return
    with STATE.lock:
        members = list(STATE.dca_members.get(dca_idx, []))
    for c in members:
        cur = get_value("ch_fader", c)
        if cur is None:
            continue
        tgt = db_to_fader(min(max(STATE.fader_to_db(cur) + delta, -90.0), 10.0))
        set_value("ch_fader", c, tgt, source="dca")


def get_name(group, idx):
    with STATE.lock:
        return STATE.names.get((group, idx), "")


def set_name(group, idx, name):
    name = str(name).strip()[:12]
    # 延迟导入: state→persist 与 persist→state/bridge 会成环, 只在函数体内打破
    # (合成单文件形态下该行被剥离, 同一命名空间直接解析)。
    with STATE.lock:
        if name:
            STATE.names[(group, idx)] = name
        else:
            STATE.names.pop((group, idx), None)
    log("NAME %s %s = %s" % (group, idx, name or "(已清除)"))
    save_user_config()          # 网页或 OSC 改名都持久化, 重启不丢
    return name


def target_label(group, idx):
    """日志用目标描述: 有名字显示 名字(编号), 没有显示 组 编号。"""
    n = get_name(group, idx)
    if n:
        return "%s(%s%02d)" % (n, KIND_LABEL.get(group, group), idx)
    return "%s %02d" % (KIND_LABEL.get(group, group), idx)


def value_reply(kind, idx):
    """(kind, idx) → 状态回包的 OSC 消息。

    返回 None 表示**当前控台不支持该目标**（调用方须过滤掉，不能塞进 bundle）。
    """
    v = get_value(kind, idx)
    a = addr_for_write(kind, idx)
    if a is None or v is None:
        return None
    if kind == "ch_dca":
        return OscMsg(a, [int(v)])
    if kind.endswith("_fader") or kind == "fx_mix" or fx_par_num(kind) is not None:
        return OscMsg(a, [float(v)])
    if kind in ("fx_type", "fx_name"):
        return OscMsg(a, [str(v)])
    return OscMsg(a, [int(v)])


PUSH_CACHE = {}      # (kind, idx) -> 上次推送的值; 状态变化推给订阅者 (真台 /xremote 行为)
PUSH_KINDS = (list(FADER_ADDR.keys()) + list(ON_ADDR.keys()))


def _push_state_diffs(sock, subscribers):
    """每次 tick 对比缓存, 把发生变化的推子/静音推给订阅者 (模拟真台变更推送)。"""
    sent = 0
    counts = profile().counts
    for kind in PUSH_KINDS:
        ids = [0] if kind.startswith("main_") else \
            range(1, counts.get(kind_group(kind), 0) + 1)
        for i in ids:
            v = get_value(kind, i)
            if v is None:
                continue
            key = (kind, i)
            old = PUSH_CACHE.get(key)
            if old is not None and abs(old - v) < 1e-4:
                continue
            PUSH_CACHE[key] = v
            reply = value_reply(kind, i)
            if reply is None:      # 当前控台没有这个目标的地址 → 不推送
                continue
            pkt = encode_message(reply)
            for s in subscribers:
                try:
                    sock.sendto(pkt, s)
                    sent += 1
                except OSError:
                    pass
    return sent


def meter_streamer(sock):
    """每 150ms 向所有订阅者推送 /meters/1 blob + 台面变更推送; 30 秒无续期的订阅者自动剔除。"""
    while True:
        time.sleep(0.15)
        now = time.time()
        with METER_LOCK:
            stale = [s for s, ts in METER_SUBSCRIBERS.items() if now - ts > 30.0]
            for s in stale:
                METER_SUBSCRIBERS.pop(s, None)
            if stale:
                log("METER 清理失活订阅者: %d 个" % len(stale))
            subscribers = list(METER_SUBSCRIBERS)
        if not subscribers:
            continue
        floats = compute_levels()
        blob = struct.pack(">i", len(floats))
        for v in floats:
            blob += struct.pack(">f", v)
        pkt = encode_message(OscMsg("/meters/1", [blob]))
        for s in subscribers:
            try:
                sock.sendto(pkt, s)
            except OSError:
                pass
        try:
            _push_state_diffs(sock, subscribers)
        except Exception as e:
            log("推送台面变更出错: %r" % e)


def compute_levels():
    """返回当前电平 dB 列表:32 输入通道 + 16 输出 Bus (UDP 推送与 Web 界面共用)。"""
    t = time.time() - START_TIME
    floats = []
    with STATE.lock:
        for group, count in ((STATE.ch, 32), (STATE.bus, 16)):
            for i in range(1, count + 1):
                ch = group[i]
                if not ch["on"]:
                    floats.append(-32768.0)  # -∞
                    continue
                db = STATE.fader_to_db(ch["fader"])
                # 模拟动态信号: 正弦 + 伪随机起伏
                wiggle = 4.0 * math.sin(t * 1.7 + i * 0.9) + 2.0 * math.sin(t * 4.3 + i * 2.3)
                floats.append(max(-60.0, min(0.0, db + wiggle)))
    return floats
NOTIFY_LAST = {}     # 手动变更推送节流: (kind, idx) -> [上次推送的值, 时间]
                     # ⚠️ 必须**连同值一起**判断"是否重复": 只看时间会把真台的面板干预挤掉。
                     # 桥接时本地渐变每 tick 都转发一次, 真台把转发也当手动变更 → 时间戳被
                     # 持续刷新; 等真正的干预到达, "距上次 < 80ms" 恒成立, 立即推送被丢,
                     # 只剩 150ms 周期推送, 而那时干预值已被下一 tick 的渐变值覆盖,
                     # 推出去的值 equals 渐变值 → 被回声抑制吸收 → 冲突永远检测不到。

# ---- 冲突策略: 手动干预只停该通道, 其余动作继续 ----
# 卡片执行期间, 正在被渐变驱动的 (kind, idx) 登记在 FADE_ZONE;
# 此时有手动写入 (网页推子 / 控制键 / 外部 OSC) 命中同一通道,
# 只把该通道标记为手动接管 (停在手动位置), 卡片其余通道与后续动作照常执行, 并推送网页通知。
FADE_LOCK = threading.Lock()
FADE_ZONE = {}        # (kind, idx) -> 卡片名 (正在被卡片渐变驱动)
INTERRUPTS = set()    # 本轮渐变中被手动接管的 (kind, idx)


def _register_fade(targets, card_name):
    """渐变开始: 登记驱动通道, 并清掉这些通道上一轮的接管标记 (后续动作重新获得控制权)。"""
    with FADE_LOCK:
        for k, i, _a, _b in targets:
            INTERRUPTS.discard((k, i))
            FADE_ZONE[(k, i)] = card_name


def _unregister_fade(targets):
    with FADE_LOCK:
        for k, i, _a, _b in targets:
            FADE_ZONE.pop((k, i), None)


def _check_manual_takeover(kind, idx):
    """手动写入前检查: 该通道正被卡片渐变驱动 → 标记接管 + 记通知事件。"""
    key = (kind, idx)
    with FADE_LOCK:
        zone = FADE_ZONE.get(key)
        if not zone or key in INTERRUPTS:
            return
        INTERRUPTS.add(key)
    text = "⚠️ %s 手动接管 — 卡片「%s」停止驱动该通道, 其余动作继续" % (
        target_label(kind_group(kind), idx), zone)
    EVT_SEQ[0] += 1
    EVENTS.append({"id": EVT_SEQ[0], "time": time.strftime("%H:%M:%S"), "text": text})
    log("CONFLICT %s" % text)


def _interrupted(kind, idx):
    return (kind, idx) in INTERRUPTS


NOTIFY_LOCK = threading.Lock()   # 只护 NOTIFY_LAST (原来借用 BRIDGE_LOCK,
                                #  那会让 state 依赖 bridge —— 模块化要切断)


class WriteSink:
    """写出口协议: set_value 落库后, 把**落库后的值**交给注册的 sink。

    为什么需要: 曾经的写法是 set_value 尾部直接调 _bridge_forward ——
    state 因此 import bridge, 层级关系倒挂; 而且转发的是调用入参,
    本地钳到 1.0 真台却收到 1.7 (B0-2)。SINKS 注册制把这两件事一起解决:
    state 不知道谁在听, sink 也拿不到原始值。
    """

    def on_write(self, kind, idx, value, source):
        raise NotImplementedError


SINKS = []        # 由 app.py 注册 (桥接 sink); 状态层不 import 任何业务模块


# ==================================================================
# ==== x32sim/bridge.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/bridge — 桥接真台: 转发合并 / 回读 / 回声抑制"""

import math
import socket
import threading
import time



def _bridge_forward(kind, idx, value, source="manual", force=False):
    """桥接模式下把写入转成 OSC 发往真台, 并登记回声抑制记录。

    入参 value 必须是**已经过本地钳制/消毒的值**（调用方传 get_value 的结果）——
    真台收到什么, 就应该和本地台面看到的一致, 不能再出现"本地 1.0 / 真台 1.7"。
    source 决定合并限速档位 (手动灵敏 / 渐变放宽), 见 BRIDGE_FWD_MIN_GAP。
    force=True 用于"停止时同步冻结值": 绕过限速下一拍必出 (gap=0),
    保证卡片/回归中途停止后真台与本地台面一致, 不停在中间值上。
    """
    try:
        if value is None:
            return          # 本地没有这个目标（换控台后规模不匹配等）
        if kind == "ch_dca":
            arg = int(value) & 0xFF
        elif kind in ("fx_type", "fx_name"):
            arg = str(value)[:12]
        elif kind.endswith("_fader") or kind == "fx_mix" or fx_par_num(kind) is not None:
            arg = float(value)
            # 第二道闸: 万一将来哪条路径漏了 _finite, 宁可拒发也不把 NaN 发给真台
            if not math.isfinite(arg):
                log("BRIDGE 拒发非有限值: %s %s = %r" % (kind, idx, value))
                return
        else:
            arg = _truthy(value)
        addr = addr_for_write(kind, idx)      # ⚠️ Main 无 %02d, 必须走统一映射 (见该函数注释)
        if addr is None:
            # 当前控台不支持这个目标 → 明说, 不要静默吞掉 (静默是这类 bug 的老家)
            p = profile()
            log("BRIDGE 跳过 %s %s: 当前控台「%s」未提供该地址%s"
                % (kind, idx, p.label, "（驱动待标定）" if not p.ready else ""))
            return
        sock = BRIDGE_SOCK[0]
        if sock is None:
            return
        # 渐变插值遇"已手动接管": 这条值是接管前算出来的, 发出去会把真台拽回
        # 旧位置, 回读回声还会把本地也覆盖回旧值 (用户白接管了)。入口就拦掉。
        # 显式动作 (set/mute/回归...) 不走这支 —— 它们的语义是"其余动作继续"。
        from_fade = (source == "fade")
        if from_fade and (kind, idx) in INTERRUPTS:
            return
        # 进合并队列 (同地址只保留最新值), 由 _bridge_fwd_flusher 按 Bundle 发出;
        # FWD_RECENT 也在实际发出时登记 —— 回声抑制要对得上真台真正收到的值。
        gap = 0.0 if force else BRIDGE_FWD_MIN_GAP.get(source, BRIDGE_FWD_GAP_DEFAULT)
        with BRIDGE_FWD["lock"]:
            BRIDGE_FWD["pending"][(kind, idx)] = (addr, arg, gap, from_fade)
    except Exception as e:
        log("BRIDGE 转发失败 %s: %r" % (kind, e))


def _bridge_force_sync(keys, skip_interrupted=False):
    """把一批 (kind, idx) 的**当前本地值**立即转发给真台 (绕过合并限速)。

    用于渐变被中途停止的场景: 本地冻结在当前值, 而最后一次插值可能还没
    转发 (或被合并器限速挡着) —— 不同步的话真台停在中间值, 与台面不一致。
    keys 是可迭代的 (kind, idx); 内部取快照, 调用方无需加锁。
    skip_interrupted: 跳过已被手动接管的通道 (卡片停止时用 —— 那些通道
    归手动管, 停止同步不该把它们拽回本地值)。
    """
    if BRIDGE["addr"] is None:
        return
    n = 0
    for kind, idx in list(keys):
        if skip_interrupted and (kind, idx) in INTERRUPTS:
            continue
        v = get_value(kind, idx)
        if v is None:
            continue
        _bridge_forward(kind, idx, v, source="action", force=True)
        n += 1
    if n:
        log("BRIDGE 停止同步: %d 个目标当前值已强制转发" % n)


def _bridge_fwd_flusher():
    """常驻合并器外壳: 任何异常写日志重启, 不静默死亡 (死亡=转发永远停)。"""
    while True:
        try:
            _bridge_fwd_flush_once()
        except Exception as e:
            log("BRIDGE 合并器异常 (已自动重启): %r" % e)
            time.sleep(0.5)


def _bridge_fwd_flush_once():
    """一轮合并发送: 把到期的转发条目打包成一个 Bundle 发给真台。"""
    time.sleep(BRIDGE_FWD_TICK)
    sock = BRIDGE_SOCK[0]
    addr = BRIDGE["addr"]
    if sock is None or addr is None:
        with BRIDGE_FWD["lock"]:
            if BRIDGE_FWD["pending"]:
                BRIDGE_FWD["pending"].clear()
        return
    now = time.time()
    batch = []
    with BRIDGE_FWD["lock"]:
        pend = BRIDGE_FWD["pending"]
        overflow = len(pend) > BRIDGE_FWD_MAX_BATCH
        for key in list(pend.keys()):
            _a, _v, gap, from_fade = pend[key]
            if from_fade and key in INTERRUPTS:
                # 接管发生后积压的渐变插值: 过期, 直接丢弃 (真台不能收到它,
                # 否则会把用户刚抢回的手动值拽回旧位置, 回读回声还会覆盖本地)
                pend.pop(key)
                continue
            if overflow or now - BRIDGE_FWD["last"].get(key, 0.0) >= gap:
                batch.append((key, pend.pop(key)))
        for key, _av in batch:
            BRIDGE_FWD["last"][key] = now
    if not batch:
        return
    msgs = [OscMsg(a, [v]) for _k, (a, v, _g, _f) in batch]
    try:
        sock.sendto(encode_bundle(msgs), addr)
    except OSError as e:
        log("BRIDGE 合并转发失败 (%d 条): %r" % (len(msgs), e))
        return
    with BRIDGE_LOCK:
        t = time.time()
        for key, (_a, v, _g, _f) in batch:
            FWD_RECENT[key] = [v, t]


def _ensure_fwd_flusher():
    """幂等启动合并器线程 (bridge_start 每次都会调, 不能起重复)。"""
    with BRIDGE_FWD["lock"]:
        t = BRIDGE_FWD_THREAD[0]
        if t is not None and t.is_alive():
            return
        t = threading.Thread(target=_bridge_fwd_flusher, daemon=True)
        t.start()
        BRIDGE_FWD_THREAD[0] = t


def _fwd_is_echo(key, value):
    """判断一条回读是不是自己刚转发造成的回声 (值相同 + 2 秒内)。"""
    with BRIDGE_LOCK:
        rec = FWD_RECENT.get(key)
    if not rec:
        return False
    if time.time() - rec[1] >= 2.0:
        return False
    a, b = rec[0], value
    if isinstance(a, str) or isinstance(b, str):
        return str(a) == str(b)
    try:
        fa, fb = float(a), float(b)
    except (TypeError, ValueError):
        return False
    # 时间/预延迟这类原生单位参数跨度大, 绝对容差 0.02 不够用, 补一个 0.5% 相对容差
    return abs(fa - fb) <= max(0.02, abs(fb) * 0.005)


def _bridge_apply_readback(kind, idx, value):
    """真台回读: 回声(自己刚转发过的值)静默吸收; 台面上的手动变化按冲突策略处理。"""
    key = (kind, idx)
    if _fwd_is_echo(key, value):
        set_value(kind, idx, value, source="sync")     # 自己写入的回声, 只对齐本地
        return
    # 真台端的变化: 渐变驱动中的通道 → 手动接管冲突; 其余静默同步
    with FADE_LOCK:
        zone = FADE_ZONE.get(key)
        if zone and key not in INTERRUPTS:
            INTERRUPTS.add(key)
            text = "⚠️ 真台上 %s 被手动干预 — 卡片「%s」停止驱动该通道, 其余动作继续" % (
                target_label(kind_group(kind), idx), zone)
            EVT_SEQ[0] += 1
            EVENTS.append({"id": EVT_SEQ[0], "time": time.strftime("%H:%M:%S"), "text": text})
            log("CONFLICT %s" % text)
    set_value(kind, idx, value, source="sync")


def _bridge_full_sync(sock):
    """全量状态回读: 向真台发一轮 GET (Bundle), 用回包填本地台面。

    地址一律经 addr_for_write 取, 当前控台不支持的目标直接跳过 —— 这样换控台后
    不会往真台发一堆它不认识的地址。
    """
    p = profile()
    counts = p.counts
    gets = []

    def _get(kind, idx):
        a = addr_for_write(kind, idx)
        if a:
            gets.append(OscMsg(a, []))

    for tmap in (FADER_ADDR, ON_ADDR):
        for k in tmap:
            grp = kind_group(k)
            ids = [0] if k.startswith("main_") else range(1, counts.get(grp, 0) + 1)
            for i in ids:
                _get(k, i)
    for i in range(1, counts.get("ch", 0) + 1):
        _get("ch_dca", i)
    # FX 机架: 类型 / 开关 / 混合比 / 名称, 以及**当前控台效果库**里用到的全部参数号。
    # ⚠️ 参数号不再写死 1/2/4 —— 不同控台的算法参数索引可能不同, 写死等于去查错位置。
    fx_pns = set()
    for a in p.fx_algos.values():
        for key in ("time", "predelay", "damp"):
            if isinstance(a.get(key), int):
                fx_pns.add(a[key])
    for s in range(1, counts.get("fx", 0) + 1):
        for k in ("fx_type", "fx_on", "fx_mix", "fx_name"):
            _get(k, s)
        for pn in sorted(fx_pns):
            _get(fx_par_kind(pn), s)
    for chunk in (gets[x:x + 64] for x in range(0, len(gets), 64)):
        try:
            sock.sendto(encode_bundle(chunk), BRIDGE["addr"])
        except OSError as e:
            log("BRIDGE 全量同步发送失败: %r" % e)
    log("BRIDGE 全量状态同步已请求 (%d 项, 控台 %s)" % (len(gets), p.label))


def fx_pull_from_console():
    """「从真台同步效果」：主动向桥接的真台重发一轮 FX 查询，把真台的效果槽拉回本地。

    与 _bridge_full_sync 的分工：那个是桥接建立时的**全量一次**，这个是**按需**
    只刷 FX —— 现场真正常用的场景是"我在台面上换了个效果器，让控制台跟着走"。

    返回 (ok, 描述 / 错误串)。
    """
    sock = BRIDGE_SOCK[0]
    if sock is None or BRIDGE.get("addr") is None:
        return False, "未桥接真台 —— 浏览器发不了 UDP，没有桥接就没有可同步的对象"
    p = profile()
    if not p.ready or "fx" not in p.caps:
        return False, "控台「%s」的效果槽未标定，无从同步" % p.label
    pns = set()
    for a in p.fx_algos.values():
        for key in ("time", "predelay", "damp"):
            if isinstance(a.get(key), int):
                pns.add(a[key])
    sent, failed = 0, 0
    for s in range(1, int(p.counts.get("fx", 0)) + 1):
        kinds = ["fx_type", "fx_on", "fx_mix", "fx_name"] + \
                [fx_par_kind(pn) for pn in sorted(pns)]
        for kind in kinds:
            addr = p.addr(kind, s)
            if addr is None:
                continue
            try:
                sock.sendto(encode_message(OscMsg(addr, [])), BRIDGE["addr"])
                sent += 1
            except OSError as e:
                failed += 1
                log("FX 同步查询发送失败 %s: %r" % (addr, e))
    log("FX 从真台同步: 已发出 %d 条查询 (%s · %d 个效果槽)%s" % (
        sent, p.label, p.counts.get("fx", 0),
        ("，失败 %d 条" % failed) if failed else ""))
    if not sent:
        return False, "没有可用的效果查询地址（控台「%s」地址表为空）" % p.label
    return True, "已向真台查询 %d 项效果状态，回包会自动同步到混响页" % sent


def bridge_client(ip, port):
    """桥接后台线程外壳: 任何异常写日志退出, 不静默死亡。"""
    try:
        _bridge_client_run(ip, port)
    except Exception as e:
        log("BRIDGE 桥接线程异常退出: %r" % e)
        BRIDGE_SOCK[0] = None
        if BRIDGE.get("addr") == (ip, port):
            BRIDGE["addr"] = None
            BRIDGE["synced"] = False


def _bridge_client_run(ip, port):
    """桥接后台线程: 5 秒 /xremote 保活, 持续接收真台回读并同步本地。"""
    _ensure_fwd_flusher()            # 转发合并器 (幂等; --bridge 启动参数也走这里)
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(0.5)
    BRIDGE_SOCK[0] = sock
    BRIDGE["addr"] = (ip, port)
    BRIDGE["ip"], BRIDGE["port"], BRIDGE["synced"] = ip, port, False
    BRIDGE["started"] = time.time()
    BRIDGE["last_warn"] = 0.0
    log("BRIDGE 桥接启动: 真台 %s:%d (写入转发 + /xremote 保活 + 状态回读)" % (ip, port))
    _bridge_full_sync(sock)
    BRIDGE["last_keep"] = 0.0        # 立即发首次 /xremote 完成订阅
    while BRIDGE["addr"] is not None:
        # 保活: 每 5 秒发一次 /xremote (真台 10 秒无保活会取消遥控链接)
        if time.time() - BRIDGE["last_keep"] >= 5.0:
            try:
                sock.sendto(encode_message(OscMsg("/xremote", [])), (ip, port))
                BRIDGE["last_keep"] = time.time()
            except OSError:
                pass
        # 真台长期无回包 → 每 30 秒提示一次 (排查 IP / 网线 / 是否同网段)
        ref = max(BRIDGE["last_recv"], BRIDGE.get("started", 0.0))
        if time.time() - ref > 20.0 and time.time() - BRIDGE["last_warn"] > 30.0:
            BRIDGE["last_warn"] = time.time()
            log("BRIDGE 真台无回包 (%s:%d) — 请检查地址、网线与是否在同一网段" % (ip, port))
        # 收真台回包/推送
        end = time.time() + 0.5
        while time.time() < end and BRIDGE["addr"] is not None:
            try:
                data, addr = sock.recvfrom(4096)
            except socket.timeout:
                break
            except OSError:
                break
            BRIDGE["last_recv"] = time.time()
            if addr[0] != ip:
                continue
            try:
                msgs = decode_packet(data)
            except Exception:
                continue
            for msg in msgs:
                a = msg.address
                if a.startswith("/meters") or a == "/xinfo" or a.startswith("/xremote"):
                    continue
                matches = match_address(a)
                if not matches or not msg.args:
                    continue
                raw = msg.args[0]
                if isinstance(raw, str) and raw:
                    try:
                        raw = float(raw)
                    except ValueError:
                        continue
                for k, i in matches[:1]:
                    try:
                        _bridge_apply_readback(k, i, raw)
                    except Exception as e:
                        log("BRIDGE 回读处理出错 %s: %r" % (a, e))
    BRIDGE_SOCK[0] = None
    BRIDGE["synced"] = False
    log("BRIDGE 桥接已断开 (%s:%d)" % (ip, port))


def bridge_start(addr_str):
    """启动桥接 (网页设置或 --bridge 参数): addr_str = 'IP:PORT'。"""
    try:
        ip, p = str(addr_str).strip().rsplit(":", 1)
        port = int(p)
    except (ValueError, AttributeError):
        return False, "地址格式应为 IP:端口"
    if not ip:
        return False, "地址格式应为 IP:端口"
    # 端口校验与 /api/ports 用同一个 valid_port，别处严、这里松
    if not (1 <= port <= 65535):
        return False, "端口必须是 1–65535"
    # 已有桥接先停
    bridge_stop()
    BRIDGE["addr"] = (ip, port)      # 先占位, 让线程启动前 set_value 也能拿到
    BRIDGE["ip"], BRIDGE["port"] = ip, port
    _ensure_fwd_flusher()            # 转发合并器 (常驻幂等)
    threading.Thread(target=bridge_client, args=(ip, port), daemon=True).start()
    return True, "桥接已启动 → %s:%d" % (ip, port)


def bridge_stop():
    if BRIDGE["addr"] is not None:
        ip, port = BRIDGE["addr"]
        BRIDGE["addr"] = None
        with BRIDGE_FWD["lock"]:
            BRIDGE_FWD["pending"].clear()   # 断开后不再有真台可发, 别留着旧值
        log("BRIDGE 停止桥接 (%s:%d)" % (ip, port))

# ---- 桥接模式: 网页/卡片写入转发到真台 (OSC), 真台状态回读同步到本地 ----
# 离线验证: 再开一个模拟器实例当"假真台", 本实例 --bridge 127.0.0.1:假台端口
BRIDGE = {"addr": None, "ip": "", "port": 0, "synced": False,
          "last_keep": 0.0, "last_recv": 0.0, "started": 0.0, "last_warn": 0.0}
BRIDGE_SOCK = [None]
BRIDGE_LOCK = threading.Lock()
# ⚠️ 可变容器: 网页断开/连接与配置加载都会改写它, main() 启动时要读最新值。
BRIDGE_TARGET = [""]   # 记住上次连过的真台地址, 下次启动自动重连 (B3 零配置的关键)
FWD_RECENT = {}      # (kind, idx) -> [value, time] 最近转发记录, 用于抑制回读回声

# ---- 桥接转发合并器 (治"写风暴") ----
# ⚠️ 曾经每条写入都单独 sendto: fade_all 时 80 个地址 × 20Hz ≈ 1000+ 个 UDP 包/秒,
#    真台 OSC 栈被刷满 (本机也忙)。现在高频写入先进合并队列 (同地址只留最新值),
#    由常驻线程每 20ms 按 **一个 Bundle** 发出:
#      - 同一地址按来源限速: 手动(用户拖推子) 50ms 保灵敏, 卡片/回归渐变 250ms
#       (真台 4Hz 跟随电动推子无感知, 而 fade_all 的包量直接降一个量级);
#      - 包数降一个量级 (真台每包只 recvfrom + 解析一次);
#      - **最后一个值一定送达**: pending 始终只留最新值, 渐变到点/被停止后,
#        一拍 (≤20ms + 间隔) 内一定发出, 不会卡在中间值上。
BRIDGE_FWD_MIN_GAP = {"manual": 0.05, "fade": 0.25, "action": 0.25, "dca": 0.1}
BRIDGE_FWD_GAP_DEFAULT = 0.1
BRIDGE_FWD_TICK = 0.02       # 合并器轮询间隔
BRIDGE_FWD_MAX_BATCH = 256   # 单拍最多发出条数 (防极端堆积把 UDP 包撑爆)
BRIDGE_FWD = {"pending": {}, "last": {}, "lock": threading.Lock()}
BRIDGE_FWD_THREAD = [None]


class _BridgeSink(WriteSink):
    """桥接写入转发 (作为写出口注册进 state.SINKS)。

    门槛条件 (原 set_value 尾部的 if) 收在这里: 桥接未连接或来源不在
    转发范围时直接返回。一律使用调用方传来的 after 值。
    """

    def on_write(self, kind, idx, value, source):
        if BRIDGE["addr"] is None or source not in ("manual", "action", "dca", "fade"):
            return
        _bridge_forward(kind, idx, value, source)


BRIDGE_SINK = _BridgeSink()


